using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedCriticalEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedCritical Effect")]
public class CorruptedCriticalEffect : Effect
{
	[Header("Critical Multiplier")]
	[SerializeField]
	private int criticalMultiplierAmount;

	[SerializeField]
	private MapHandler mapHandler;

	protected override string GetLocalizedDescription()
	{
		if (GameScenesUtils.IsMainMenu())
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptedCriticalAstrea_D");
		}
		if (mapHandler.BossBattle)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("CorruptedCriticalAstrea_D");
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(EffectID + "_D");
	}

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), criticalMultiplierAmount);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, criticalMultiplierAmount);
	}

	public int GetCorruptionAmount(int chanceAmount, int corruptionAmount, UnitEffects unitEffects)
	{
		if (unitEffects.GetComponent<CorruptionStats>().IsDefeated())
		{
			return 0;
		}
		if (RandomUtilities.RandomChance(chanceAmount))
		{
			unitEffects.IsEffectActive(this);
			SpawnVFX(GetVFXOwnerPosition(unitEffects.gameObject), 3f);
			if (IsVFXEnabled())
			{
				PlayEffectActivationSFX();
			}
			return GetCriticalCorruption(corruptionAmount);
		}
		return corruptionAmount;
	}

	private int GetCriticalCorruption(int amount)
	{
		return amount * criticalMultiplierAmount;
	}
}
